from pathlib import Path
p=Path('tests/v061-browser.py');s=p.read_text();assert "=='0.6.1'" in s;p.write_text(s.replace('0.6.1','0.6.2'))
p=Path('tests/v062-browser.py');s=p.read_text()
old="    done('Released ZIP bytes match the tested extension source')"
new=old+"\n    import subprocess, sys\n    subprocess.run([sys.executable,str(ROOT/'tests/v061-browser.py')],cwd=ROOT,check=True)\n    done('Prior native layout, palette, settings and cart regression suite passed')\n    subprocess.run([sys.executable,str(ROOT/'tests/cart-builder-browser.py')],cwd=ROOT,check=True)\n    done('Prior native cart grades, package sizes, clear glass and preview regression suite passed')"
assert old in s;p.write_text(s.replace(old,new,1))
p=Path('README.md');s=p.read_text()
intro='''\n## v0.6.2: selected-grade photos throughout the app\n\nPowder, Fine, Medium and Coarse now control the actual Bullseye photograph in the main palette, All glass, alternatives, enlarged details and every cart view. These views use the same verified photo selector and the existing 838-listing photo index. Jar weight is independent of frit grain size. Switching grades while details are open refreshes the displayed photo without allowing an earlier image request to replace it.\n\nThe selected-grade product photo no longer carries sample coordinates from another photograph. The existing medium-frit sampling image, swatches and thickness estimates remain together under **Thickness color reference · Medium frit** in the detail window. Your source image, colors, dots and chosen matches are unchanged.\n\n'''
s=s.replace('\n', '\n'+intro,1).replace('Bullseye-Palette-Picker-v0.6.1.zip','Bullseye-Palette-Picker-v0.6.2.zip')
s=s.replace('All formats reuse the reviewed medium-frit photographs and color samples;', 'All formats retain the reviewed medium-frit color samples for matching and thickness estimates, separately from the actual selected-grade product photographs;')
